import numpy as np

def consensus_step(x, edges, eps):
    """x: array of shape (n,) or (n, d), one row per robot. edges: list of undirected links (i, j).
    Return the new values after one step of x_i <- x_i + eps * sum over neighbours j of (x_j - x_i)."""
    x = np.asarray(x, dtype=float)
    return x.copy()

def first_conflict(path_a, path_b):
    """Paths are lists of cells, one per time step; a robot that has finished waits at its last cell.
    Return ("vertex", t) or ("swap", t) for the earliest conflict (a vertex conflict first if both
    happen at the same t), or None if the paths are compatible."""
    for t, (a, b) in enumerate(zip(path_a, path_b)):
        if a == b:
            return ("vertex", t)
    return None

